class BookIn(BaseModel):
    """Payload for creating a new book."""

    title: str = Field(min_length=1)
    author: str
    year: int = Field(ge=1450, le=2100)


@app.get("/books")

@app.get("/books/{book_id}")
def get_book(book_id: int):
    """Return one book by id."""
    book = BOOKS.get(book_id)
    if book is None:
        raise HTTPException(status_code=404, detail="Book not found")
    return book


@app.post("/books", status_code=201)
def create_book(book: BookIn):
    """Add a new book to the shelf and return it."""
    new_id = max(BOOKS, default=0) + 1
    new_book = {"id": new_id, **book.model_dump()}
    BOOKS[new_id] = new_book
    return new_book

